        r = (z - T2[i].chi - T2[i].clo) * invc;
        rhi = asdouble(asuint64(r) & -1ULL << 32);
        rlo = r - rhi;
        t1 = rhi * InvLn2hi;
        t2 = rlo * InvLn2hi + r * InvLn2lo;
